<?php require __DIR__.'/config/db.php';require __DIR__.'/includes/auth.php';require_role(['admin']);$pageTitle='Admin';$students=$pdo->query('SELECT * FROM students ORDER BY full_name')->fetchAll();$users=$pdo->query('SELECT name,email,role,is_active FROM users ORDER BY role,name')->fetchAll();require __DIR__.'/includes/header.php';?>
<h1>Admin overview</h1><section class="panel"><h2>Students</h2><div class="tablewrap"><table><tr><th>Student no.</th><th>Name</th><th>Department</th><th>Year</th><th>Email</th></tr><?php foreach($students as $s):?><tr><td><?=h($s['student_no'])?></td><td><?=h($s['full_name'])?></td><td><?=h($s['department'])?></td><td><?=$s['year_level']?></td><td><?=h($s['email'])?></td></tr><?php endforeach;?></table></div></section><section class="panel"><h2>Users</h2><div class="tablewrap"><table><tr><th>Name</th><th>Email</th><th>Role</th><th>Active</th></tr><?php foreach($users as $x):?><tr><td><?=h($x['name'])?></td><td><?=h($x['email'])?></td><td><?=h($x['role'])?></td><td><?=$x['is_active']?'Yes':'No'?></td></tr><?php endforeach;?></table></div></section><?php require __DIR__.'/includes/footer.php';?>